export const glossary=[['ARR','Redução absoluta de risco: diferença de risco entre controle e intervenção, no horizonte analisado.'],['CVOT','Cardiovascular outcome trial: ensaio de desfechos cardiovasculares.'],['DPP-4','Enzima que degrada incretinas. Inibi-la não equivale a administrar um agonista de GLP-1.'],['DRC','Doença renal crônica. Estágio e albuminúria importam para aplicar evidências.'],['Estimando','Definição precisa do efeito que o estudo pretende estimar, inclusive como lida com interrupção e resgate.'],['GIP','Polipeptídeo insulinotrópico dependente de glicose.'],['GLP-1','Peptídeo semelhante ao glucagon tipo 1.'],['HbA1c','Hemoglobina glicada; sua redução em pontos percentuais difere de redução relativa de risco.'],['HFpEF / ICFEp','Insuficiência cardíaca com fração de ejeção preservada.'],['HR','Hazard ratio: razão dos riscos instantâneos; não é automaticamente risco relativo acumulado.'],['IC95%','Intervalo de confiança de 95%; informa precisão da estimativa dentro das premissas do modelo.'],['KCCQ-CSS','Escore clínico de sintomas e limitações na insuficiência cardíaca; mais alto representa melhor estado.'],['MACE','Eventos cardiovasculares maiores; conferir definição exata em cada ensaio.'],['MASLD / MASH','Doença hepática esteatótica associada à disfunção metabólica / esteato-hepatite associada à disfunção metabólica.'],['MEN2','Neoplasia endócrina múltipla tipo 2, associada a risco de carcinoma medular de tireoide.'],['NNT','Número necessário para tratar: inverso da ARR, condicionado à população e ao período.'],['NOIA-NA / NAION','Neuropatia óptica isquêmica anterior não arterítica; não confundir com retinopatia diabética.'],['PAP','Pressão positiva nas vias aéreas, usada no tratamento de apneia do sono.'],['PICO','População, intervenção, comparador e desfecho: estrutura para formular uma pergunta clínica.'],['pp','Ponto percentual: diferença absoluta entre porcentagens.'],['SC','Via subcutânea.'],['Titulação','Ajuste progressivo da dose conforme intervalo, indicação e tolerabilidade.']];
